sys_script_client.script:
function onSubmit() {


    /*Artifacts Included: 

	Making the old fields read only as part of MSSCUSTODY-6022 since the duplicate fields are available for the user selection
    1) Client Script: MSS Bulk Prepopulate Amend from Trade
    2) Script Include: x_hsb11_mss_c_proc.MSSCustodyAmendUtils - evalAmendEligibility
    3) Script Include: x_hsb11_hsbc_mss_o.MSSAmendUtilsCore - getTradeFieldvaluesForBulk
    4) System Property: x_hsb11_mss_c_proc.enableautomatedamend.market
    5) System Property: x_hsb11_mss_c_proc.enableautomatedamend.outcomes

    */

    /*
    Artifacts Included:
    1) Client Script - MSS Amend Bulk Copy Remote Table Fields - To pass values from Clien
    2) Script Include -x_hsb11_mss_c_proc.MSSCustodyAmendUtils - evalAmendEligibility -  Controlled Execution for only Amend Outcomes
    3) Script Include: - x_hsb11_hsbc_mss_o.MSSAmendUtilsCore- setBulkFieldValuesForAmend- Update Bulk Record 
    */

    var securityID = g_form.getDisplayBox('amend_security_id_sec_id_ref').value; //remote Table field
    var trdDate = g_form.getValue('amend_trade_date');
    var settlementDate = g_form.getValue('settlement_date');
    var settlementCurrency = g_form.getValue('amend_settlement_currency');
    var settlementAmount = g_form.getValue('amend_settlement_amount');
    var dealCurrency = g_form.getValue('amend_deal_currency');
    var dealPrice = g_form.getValue('amend_deal_price');
    var countRef = g_form.getValue('counterparty_reference');
    var cuRef = g_form.getValue('customer_reference');
    var locCode = g_form.getValue('amend_location_code');
    var hmiIndicator = g_form.getValue('amend_hmi_indicator');
    var scriptIndicator = g_form.getValue('amend_script_hold_indicator');
    var cashIndicator = g_form.getValue('amend_cash_hold_indicator');
    var gdiIndicator = g_form.getValue('amend_gdi_indicator');
    var payMethod = g_form.getValue('amend_payment_method');
    var switchIndic = g_form.getValue('amend_switch_indicator');
    var switchAccRef = g_form.getDisplayBox('amend_switch_account_ref').value; //remote Table field
    var susAccNumber = g_form.getValue('amend_suspense_account_number');
    var counterpartyCodeRef = g_form.getDisplayBox('amend_counterparty_code_ref').value; //remote Table field
    var counterpartySettAccNum = g_form.getValue('amend_counterparty_settlement_account_number');
    var accSwitch = g_form.getValue('amend_convert_to_account_switching');
    var accOfClient = g_form.getValue('amend_a_c_of_client');
    var deliverCusBic = g_form.getValue('amend_deliverer_custodian_bic_receiver_custodian_bic');
    var sellerBuyerBic = g_form.getValue('amend_seller_bic_buyer_bic');
    var placeOfSettBic = g_form.getValue('amend_place_of_settlement_bic');
    var chargeType = g_form.getValue('amend_charges_type');
    var chargeCCY = g_form.getValue('amend_charges_ccy');
    var chargeAmt = g_form.getValue('amend_charges_amt');
    var amendNSSC = g_form.getValue('amend_nssc');


    // var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
    // eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
    // eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
    // eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
    // eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
    // eligbleCheck.getXMLAnswer(handleEligiblity);


    // function handleEligiblity(check) {
    //     if (check.toString() == 'true') {
    // 		g_form.addInfoMessage('Loop 1');

    var updateBulk = new GlideAjax('x_hsb11_hsbc_mss_o.MSSAmendUtilsCore');
    updateBulk.addParam('sysparm_name', 'setBulkFieldValuesForAmend');
    updateBulk.addParam('sysparm_recSysID', g_form.getUniqueValue());
    updateBulk.addParam('sysparm_bulkGrp', g_form.getValue('bulk_field_group'));
    updateBulk.addParam('sysparm_securityID', securityID); //remote Table field
    updateBulk.addParam('sysparm_trdDate', trdDate);
    updateBulk.addParam('sysparm_settlementDate', settlementDate);
    updateBulk.addParam('sysparm_settlementCurrency', settlementCurrency);
    updateBulk.addParam('sysparm_settlementAmount', settlementAmount);
    updateBulk.addParam('sysparm_dealCurrency', dealCurrency);
    updateBulk.addParam('sysparm_dealPrice', dealPrice);
    updateBulk.addParam('sysparm_countRef', countRef);
    updateBulk.addParam('sysparm_cuRef', cuRef);
    updateBulk.addParam('sysparm_locCode', locCode);
    updateBulk.addParam('sysparm_hmiIndicator', hmiIndicator);
    updateBulk.addParam('sysparm_scriptIndicator', scriptIndicator);
    updateBulk.addParam('sysparm_cashIndicator', cashIndicator);
    updateBulk.addParam('sysparm_gdiIndicator', gdiIndicator);
    updateBulk.addParam('sysparm_payMethod', payMethod);
    updateBulk.addParam('sysparm_switchIndic', switchIndic);
    updateBulk.addParam('sysparm_switchAccRef', switchAccRef); //remote Table field
    updateBulk.addParam('sysparm_susAccNumber', susAccNumber);
    updateBulk.addParam('sysparm_counterpartyCodeRef', counterpartyCodeRef); //remote Table field
    updateBulk.addParam('sysparm_counterpartySettAccNum', counterpartySettAccNum);
    updateBulk.addParam('sysparm_accSwitch', accSwitch);
    updateBulk.addParam('sysparm_accOfClient', accOfClient);
    updateBulk.addParam('sysparm_deliverCusBic', deliverCusBic);
    updateBulk.addParam('sysparm_sellerBuyerBic', sellerBuyerBic);
    updateBulk.addParam('sysparm_placeOfSettBic', placeOfSettBic);
    updateBulk.addParam('sysparm_chargeType', chargeType);
    updateBulk.addParam('sysparm_chargeCCY', chargeCCY);
    updateBulk.addParam('sysparm_chargeAmt', chargeAmt);
    updateBulk.addParam('sysparm_amendNSSC', amendNSSC);
    updateBulk.getXMLAnswer(handleEligiblity);


    function handleEligiblity() {
        //
    }

    //}




    //}

}
